import React, { useState } from "react";

const BASE = "/img/main_imges_folder/";
const WIDTHS = [480, 960, 1600];

// Project photo with downscaled WebP variants (generated by the server, see
// server/imageVariants.js) so a phone on a weak connection downloads a few
// dozen KB instead of the multi-MB original. If a variant is missing (a photo
// not processed yet) the image falls back to the original file.
const ResponsiveImg = ({
  file,
  alt = "",
  sizes = "100vw",
  eager = false,
  priority = false,
  ...rest
}) => {
  const [useOriginal, setUseOriginal] = useState(false);
  const original = `${BASE}${file}`;

  // File name not known yet (data still loading): render nothing instead of
  // requesting ".../undefined".
  if (!file) return null;

  if (useOriginal) {
    return <img src={original} alt={alt} {...rest} />;
  }

  // encodeURI: some uploaded names contain spaces, which would break the
  // srcset candidate list.
  const srcSet = WIDTHS.map(
    (w) => `${BASE}${encodeURI(file)}.w${w}.webp ${w}w`
  ).join(", ");

  return (
    <img
      src={`${BASE}${encodeURI(file)}.w960.webp`}
      srcSet={srcSet}
      sizes={sizes}
      alt={alt}
      loading={eager || priority ? "eager" : "lazy"}
      decoding="async"
      fetchpriority={priority ? "high" : undefined}
      onError={() => setUseOriginal(true)}
      {...rest}
    />
  );
};

export default ResponsiveImg;
